                parsed = _search(lines[j])
                if parsed:
                    return "{:04d}-{:02d}-{:02d}".format(*parsed)

    # Fallback: first valid date anywhere in the text.
    for line in lines:
        parsed = _search(line)
        if parsed:
            return "{:04d}-{:02d}-{:02d}".format(*parsed)

