# Allow numbers like 1,234.56 or 123.45 or "29. 00" (space after dot) or "538 00" (space instead of dot).


def _parse_amount(s):
    s = s.replace(",", "").replace(" ", "")
    if "." not in s:
        # Insert decimal point before last two digits if plausible.
        if len(s) >= 3 and s.isdigit():
            s = s[:-2] + "." + s[-2:]
        else:
            return None
    try:
        d = Decimal(s)
    except InvalidOperation:
        return None
    # Normalise to 2 decimals.
    return f"{d:.2f}"


def _amounts_in_line(line):
    """Return list of (position, formatted_amount) in a line, left to right."""
    matches = []
    # Prefer numbers that already have a decimal.
    for m in re.finditer(r"\d{1,3}(?:,\d{3})+\.\s?\d{1,2}|\d+\.\s?\d{1,2}", line):
        amt = _parse_amount(m.group(0))
        if amt is not None:
            matches.append((m.start(), amt))
    if not matches:
        # Fallback: "538 00" style - treat trailing " \d{2}" as decimal.
        for m in re.finditer(r"\b(\d{1,3}(?:,\d{3})*)\s(\d{2})\b", line):
            s = m.group(1).replace(",", "") + "." + m.group(2)
            amt = _parse_amount(s)
            if amt is not None:
                matches.append((m.start(), amt))
    return matches


def extract_total(text):
    """Extract total amount string using tiered keyword search."""
    lines = text.splitlines()
    upper_lines = [l.upper() for l in lines]

    def _line_excluded(ul):
        return any(kw in ul for kw in EXCLUSIONS)

    def _tier_match(ul, keywords):
        return any(kw in ul for kw in keywords)

    for tier in TIER_KEYWORDS:
        candidates = []  # (line_index, amount)
        for i, ul in enumerate(upper_lines):
            if _line_excluded(ul):
                continue
            if not _tier_match(ul, tier):
                continue
            amts = _amounts_in_line(lines[i])
            if amts:
                # Take the rightmost amount on the keyword line.
                candidates.append((i, amts[-1][1]))
            else:
                # Fallback: look at the next non-empty line.
                for j in range(i + 1, min(i + 3, len(lines))):
                    if not lines[j].strip():
                        continue
                    if _line_excluded(upper_lines[j]):
                        break
                    amts_next = _amounts_in_line(lines[j])
                    if amts_next:
                        candidates.append((i, amts_next[-1][1]))
                    break
        if candidates:
            # Prefer the LAST candidate (usually the final rounded total).
            return candidates[-1][1]
    return None


def process_image(img_path):
    outputs = ocr_variants(img_path)
    combined = "\n".join(outputs)

    date_iso = None
    total_amt = None

    # Try per-variant first for cleaner matches, then combined as fallback.
    for text in outputs:
        if date_iso is None:
            date_iso = extract_date(text)
        if total_amt is None:
            total_amt = extract_total(text)
        if date_iso and total_amt:
