    if date_iso is None:
        date_iso = extract_date(combined)
    if total_amt is None:
        total_amt = extract_total(combined)

    return date_iso, total_amt


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    filenames = sorted(
        f for f in os.listdir(SRC_DIR)
        if f.lower().endswith((".jpg", ".jpeg", ".png"))
    )

    for name in filenames:
        path = os.path.join(SRC_DIR, name)
        date_iso, total_amt = process_image(path)
        print(f"{name}: date={date_iso}, total={total_amt}")
        ws.append([name, date_iso, total_amt])

    wb.save(OUT_FILE)
    print(f"Saved {OUT_FILE}")


if __name__ == "__main__":
    main()
