EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST",
              "DISCOUNT", "CHANGE", "CASH TENDERED"]


def ocr_variants(img_path):
    """Run multiple OCR passes and return a list of raw text outputs."""
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)

    # Upscale small images 2x for better recognition.
    w, h = gray.size
    if max(w, h) < 1500:
        gray_up = gray.resize((w * 2, h * 2), Image.Resampling.LANCZOS)
    else:
        gray_up = gray

    variants = [
        gray,
        gray_up,
        ImageOps.autocontrast(gray_up),
        gray_up.filter(ImageFilter.SHARPEN),
    ]

    psms = ["--psm 6", "--psm 4"]

    outputs = []
    for v in variants:
        for psm in psms:
            try:
                outputs.append(pytesseract.image_to_string(v, config=psm))
            except Exception:
                pass
    return outputs


def _is_valid_date(y, m, d):
    try:
        datetime.date(y, m, d)
        return True
    except ValueError:
        return False


def extract_date(text):
    """Extract ISO date (YYYY-MM-DD) from text. Returns None if not found."""
    lines = text.splitlines()

    # Find "Date"-labelled lines first to anchor the search.
    date_label = re.compile(r"\b(date|dated|tarikh)\b", re.IGNORECASE)
    labelled_hits = []
    for i, line in enumerate(lines):
        if date_label.search(line):
            labelled_hits.append(i)

    def _parse_match(m):
        groups = m.groups()
        if m.re.pattern == NUMERIC_SLASH_FULL.pattern:
            a, b, y = int(groups[0]), int(groups[1]), int(groups[2])
            # Assume DD/MM/YYYY (Malaysian locale).
            d, mo = a, b
            if mo > 12 and d <= 12:
                d, mo = mo, d
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == NUMERIC_SLASH_SHORT.pattern:
            a, b, y2 = int(groups[0]), int(groups[1]), int(groups[2])
            y = 2000 + y2 if y2 < 70 else 1900 + y2
            d, mo = a, b
            if mo > 12 and d <= 12:
                d, mo = mo, d
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == ISO_DATE.pattern:
            y, mo, d = int(groups[0]), int(groups[1]), int(groups[2])
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == DMY_TEXT.pattern:
            d = int(groups[0])
            mo = MONTHS.get(groups[1].upper())
            y = int(groups[2])
            if mo and _is_valid_date(y, mo, d):
                return (y, mo, d)
        return None

    def _search(line):
        for pat in (NUMERIC_SLASH_FULL, NUMERIC_SLASH_SHORT, ISO_DATE, DMY_TEXT):
            for m in pat.finditer(line):
                parsed = _parse_match(m)
                if parsed:
                    return parsed
        return None

    # Try labelled lines first.
    for i in labelled_hits:
        for j in (i, i + 1):
            if 0 <= j < len(lines):
                parsed = _search(lines[j])
                if parsed:
                    return "{:04d}-{:02d}-{:02d}".format(*parsed)

    # Fallback: first valid date anywhere in the text.
    for line in lines:
        parsed = _search(line)
        if parsed:
            return "{:04d}-{:02d}-{:02d}".format(*parsed)

    return None


NUMERIC_SLASH_FULL = re.compile(r"\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})\b")
NUMERIC_SLASH_SHORT = re.compile(r"\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})\b")
ISO_DATE = re.compile(r"\b(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})\b")
DMY_TEXT = re.compile(
    r"\b(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s+(\d{4})\b",
