def _parse_amount(s):
    s = s.replace(",", "").replace(" ", "")
    if "." not in s:
        if len(s) >= 3 and s.isdigit():
            s = s[:-2] + "." + s[-2:]
        else:
            return None
    try:
        d = Decimal(s)
    except InvalidOperation:
        return None
    return f"{d:.2f}"


def _amounts_in_line(line):
    """Return [(position, amount_str)] for numeric amounts in the line."""
    matches = []
    # Decimal-dot amounts (allow optional space after dot and comma thousands).
    for m in re.finditer(r"\d{1,3}(?:,\d{3})+\.\s?\d{1,2}|\d+\.\s?\d{1,2}", line):
        amt = _parse_amount(m.group(0))
        if amt is not None:
            matches.append((m.start(), amt))
    if not matches:
