    "JUL": 7, "AUG": 8, "SEP": 9, "SEPT": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

TIER_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

EXCLUSIONS = ["SUBTOTAL", "SUB TOTAL", "TAX", "GST", "SST",
              "DISCOUNT", "CHANGE", "CASH TENDERED"]


def ocr_variants(img_path):
    """Run multiple OCR passes and return a list of raw text outputs."""
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)

    # Upscale small images 2x for better recognition.
    w, h = gray.size
    if max(w, h) < 1500:
        gray_up = gray.resize((w * 2, h * 2), Image.Resampling.LANCZOS)
    else:
        gray_up = gray

    variants = [
        gray,
        gray_up,
        ImageOps.autocontrast(gray_up),
        gray_up.filter(ImageFilter.SHARPEN),
    ]

    psms = ["--psm 6", "--psm 4"]

    outputs = []
    for v in variants:
        for psm in psms:
            try:
                outputs.append(pytesseract.image_to_string(v, config=psm))
            except Exception:
                pass
    return outputs


def _is_valid_date(y, m, d):
    try:
        datetime.date(y, m, d)
        return True
    except ValueError:
        return False


def extract_date(text):
    """Extract ISO date (YYYY-MM-DD) from text. Returns None if not found."""
    lines = text.splitlines()

    # Find "Date"-labelled lines first to anchor the search.
    date_label = re.compile(r"\b(date|dated|tarikh)\b", re.IGNORECASE)
    labelled_hits = []
    for i, line in enumerate(lines):
        if date_label.search(line):
            labelled_hits.append(i)

    def _parse_match(m):
        groups = m.groups()
        if m.re.pattern == NUMERIC_SLASH_FULL.pattern:
            a, b, y = int(groups[0]), int(groups[1]), int(groups[2])
            # Assume DD/MM/YYYY (Malaysian locale).
            d, mo = a, b
            if mo > 12 and d <= 12:
                d, mo = mo, d
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == NUMERIC_SLASH_SHORT.pattern:
            a, b, y2 = int(groups[0]), int(groups[1]), int(groups[2])
            y = 2000 + y2 if y2 < 70 else 1900 + y2
            d, mo = a, b
            if mo > 12 and d <= 12:
                d, mo = mo, d
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == ISO_DATE.pattern:
            y, mo, d = int(groups[0]), int(groups[1]), int(groups[2])
            if _is_valid_date(y, mo, d):
                return (y, mo, d)
        elif m.re.pattern == DMY_TEXT.pattern:
            d = int(groups[0])
            mo = MONTHS.get(groups[1].upper())
            y = int(groups[2])
            if mo and _is_valid_date(y, mo, d):
                return (y, mo, d)
        return None

    def _search(line):
        for pat in (NUMERIC_SLASH_FULL, NUMERIC_SLASH_SHORT, ISO_DATE, DMY_TEXT):
            for m in pat.finditer(line):
                parsed = _parse_match(m)
                if parsed:
                    return parsed
        return None

    # Try labelled lines first.
    for i in labelled_hits:
        for j in (i, i + 1):
            if 0 <= j < len(lines):
                parsed = _search(lines[j])
                if parsed:
                    return "{:04d}-{:02d}-{:02d}".format(*parsed)

    # Fallback: first valid date anywhere in the text.
    for line in lines:
        parsed = _search(line)
        if parsed:
            return "{:04d}-{:02d}-{:02d}".format(*parsed)

    return None


NUMERIC_SLASH_FULL = re.compile(r"\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})\b")
NUMERIC_SLASH_SHORT = re.compile(r"\b(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})\b")
ISO_DATE = re.compile(r"\b(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})\b")
DMY_TEXT = re.compile(
    r"\b(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s+(\d{4})\b",
    re.IGNORECASE,
)


AMOUNT_RE = re.compile(r"\d{1,3}(?:,\d{3})+\.\d{1,2}|\d+\.\s?\d{1,2}|\d+\s\d{2}\b")
# Allow numbers like 1,234.56 or 123.45 or "29. 00" (space after dot) or "538 00" (space instead of dot).


def _parse_amount(s):
    s = s.replace(",", "").replace(" ", "")
    if "." not in s:
        # Insert decimal point before last two digits if plausible.
        if len(s) >= 3 and s.isdigit():
            s = s[:-2] + "." + s[-2:]
        else:
            return None
    try:
        d = Decimal(s)
    except InvalidOperation:
        return None
    # Normalise to 2 decimals.
    return f"{d:.2f}"


def _amounts_in_line(line):
    """Return list of (position, formatted_amount) in a line, left to right."""
    matches = []
    # Prefer numbers that already have a decimal.
    for m in re.finditer(r"\d{1,3}(?:,\d{3})+\.\s?\d{1,2}|\d+\.\s?\d{1,2}", line):
        amt = _parse_amount(m.group(0))
        if amt is not None:
            matches.append((m.start(), amt))
    if not matches:
        # Fallback: "538 00" style - treat trailing " \d{2}" as decimal.
        for m in re.finditer(r"\b(\d{1,3}(?:,\d{3})*)\s(\d{2})\b", line):
            s = m.group(1).replace(",", "") + "." + m.group(2)
            amt = _parse_amount(s)
            if amt is not None:
                matches.append((m.start(), amt))
    return matches


def extract_total(text):
    """Extract total amount string using tiered keyword search."""
    lines = text.splitlines()
    upper_lines = [l.upper() for l in lines]

    def _line_excluded(ul):
        return any(kw in ul for kw in EXCLUSIONS)

    def _tier_match(ul, keywords):
        return any(kw in ul for kw in keywords)

    for tier in TIER_KEYWORDS:
        candidates = []  # (line_index, amount)
        for i, ul in enumerate(upper_lines):
            if _line_excluded(ul):
                continue
            if not _tier_match(ul, tier):
                continue
            amts = _amounts_in_line(lines[i])
            if amts:
                # Take the rightmost amount on the keyword line.
                candidates.append((i, amts[-1][1]))
            else:
                # Fallback: look at the next non-empty line.
                for j in range(i + 1, min(i + 3, len(lines))):
                    if not lines[j].strip():
                        continue
                    if _line_excluded(upper_lines[j]):
                        break
                    amts_next = _amounts_in_line(lines[j])
                    if amts_next:
                        candidates.append((i, amts_next[-1][1]))
                    break
        if candidates:
            # Prefer the LAST candidate (usually the final rounded total).
            return candidates[-1][1]
    return None


def process_image(img_path):
    outputs = ocr_variants(img_path)
    combined = "\n".join(outputs)

    date_iso = None
    total_amt = None

    # Try per-variant first for cleaner matches, then combined as fallback.
    for text in outputs:
        if date_iso is None:
            date_iso = extract_date(text)
        if total_amt is None:
            total_amt = extract_total(text)
        if date_iso and total_amt:
            break

    if date_iso is None:
        date_iso = extract_date(combined)
    if total_amt is None:
        total_amt = extract_total(combined)

    return date_iso, total_amt


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    filenames = sorted(
        f for f in os.listdir(SRC_DIR)
        if f.lower().endswith((".jpg", ".jpeg", ".png"))
    )

    for name in filenames:
        path = os.path.join(SRC_DIR, name)
        date_iso, total_amt = process_image(path)
        print(f"{name}: date={date_iso}, total={total_amt}")
        ws.append([name, date_iso, total_amt])

    wb.save(OUT_FILE)
    print(f"Saved {OUT_FILE}")


if __name__ == "__main__":
    main()
