import os
import re
import datetime
from collections import Counter
from decimal import Decimal, InvalidOperation

import pytesseract
from PIL import Image, ImageOps, ImageFilter
from openpyxl import Workbook

SRC_DIR = "/app/workspace/dataset/img"
OUT_FILE = "/app/workspace/stat_ocr.xlsx"

MONTHS = {
    "JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
    "JUL": 7, "AUG": 8, "SEP": 9, "SEPT": 9, "OCT": 10, "NOV": 11, "DEC": 12,
}

TIER_KEYWORDS = [
    ["GRAND TOTAL"],
    ["TOTAL RM", "TOTAL: RM"],
    ["TOTAL AMOUNT"],
    ["TOTAL", "AMOUNT", "TOTAL DUE", "AMOUNT DUE",
     "BALANCE DUE", "NETT TOTAL", "NET TOTAL"],
]

# "GST"/"SST" exclusions skip only when not qualified by INCL/INCLUSIVE/INCLUDING
# (otherwise lines like "Total Sales (Inclusive GST)" would wrongly be skipped).
EXCL_UNCONDITIONAL = ["SUBTOTAL", "SUB TOTAL", "TAX", "DISCOUNT",
                      "CHANGE", "CASH TENDERED"]
EXCL_CONDITIONAL = ["GST", "SST"]
INCL_QUALIFIERS = ["INCL", "INCLUSIVE", "INCLUDING", "INC."]

STOP_MARKERS = ["GST SUMMARY", "TAX SUMMARY", "GST BREAKDOWN", "TAX BREAKDOWN"]
HEADER_TOKENS = ["QTY", "PRICE", "U/P", "U.P", "RSP", "CODE",
                 "DESCRIPTION", "DESC."]
ROUNDING_MARKERS = ["ROUNDING", "ROUNDED", "ROUND ADJ", "ADJ"]


def ocr_variants(img_path):
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)

    w, h = gray.size
    if max(w, h) < 1500:
        gray_up = gray.resize((w * 2, h * 2), Image.Resampling.LANCZOS)
    else:
        gray_up = gray

    variants = [
        gray,
        gray_up,
        ImageOps.autocontrast(gray_up),
        gray_up.filter(ImageFilter.SHARPEN),
    ]
    psms = ["--psm 6", "--psm 4"]

    outputs = []
    for v in variants:
        for psm in psms:
            try:
                outputs.append(pytesseract.image_to_string(v, config=psm))
            except Exception:
                pass
    return outputs


# -------- Date extraction --------

NUMERIC_SLASH_FULL = re.compile(r"(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{4})")
NUMERIC_SLASH_SHORT = re.compile(r"(?<!\d)(\d{1,2})[\-/\.](\d{1,2})[\-/\.](\d{2})(?!\d)")
ISO_DATE = re.compile(r"(\d{4})[\-/\.](\d{1,2})[\-/\.](\d{1,2})")
DMY_TEXT = re.compile(
    r"(\d{1,2})\s+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*\s+(\d{4})",
    re.IGNORECASE,
)


def _is_valid_date(y, m, d):
    try:
        datetime.date(y, m, d)
        return True
    except ValueError:
        return False


def _parse_date_components(m, pat):
    g = m.groups()
    if pat is NUMERIC_SLASH_FULL:
        a, b, y = int(g[0]), int(g[1]), int(g[2])
        d, mo = a, b
        if mo > 12 and d <= 12:
            d, mo = mo, d
        if _is_valid_date(y, mo, d):
            return y, mo, d
    elif pat is NUMERIC_SLASH_SHORT:
        a, b, y2 = int(g[0]), int(g[1]), int(g[2])
        y = 2000 + y2 if y2 < 70 else 1900 + y2
        d, mo = a, b
        if mo > 12 and d <= 12:
            d, mo = mo, d
        if _is_valid_date(y, mo, d):
            return y, mo, d
    elif pat is ISO_DATE:
        y, mo, d = int(g[0]), int(g[1]), int(g[2])
        if _is_valid_date(y, mo, d):
            return y, mo, d
    elif pat is DMY_TEXT:
        d = int(g[0])
        mo = MONTHS.get(g[1].upper())
        y = int(g[2])
        if mo and _is_valid_date(y, mo, d):
            return y, mo, d
    return None


def _search_date_in_line(line):
    for pat in (NUMERIC_SLASH_FULL, NUMERIC_SLASH_SHORT, ISO_DATE, DMY_TEXT):
        for m in pat.finditer(line):
            parsed = _parse_date_components(m, pat)
            if parsed:
                return parsed
    return None


def extract_date(text):
    lines = text.splitlines()
    label_re = re.compile(r"\b(date|dated|tarikh)\b", re.IGNORECASE)
    labelled = [i for i, l in enumerate(lines) if label_re.search(l)]

    for i in labelled:
        for j in (i, i + 1):
            if 0 <= j < len(lines):
                parsed = _search_date_in_line(lines[j])
                if parsed:
                    return "{:04d}-{:02d}-{:02d}".format(*parsed)

    for line in lines:
        parsed = _search_date_in_line(line)
        if parsed:
            return "{:04d}-{:02d}-{:02d}".format(*parsed)
    return None


# -------- Amount parsing --------


def _parse_amount(s):
    s = s.replace(",", "").replace(" ", "")
    if "." not in s:
        if len(s) >= 3 and s.isdigit():
            s = s[:-2] + "." + s[-2:]
        else:
            return None
    try:
        d = Decimal(s)
    except InvalidOperation:
        return None
    return f"{d:.2f}"


def _amounts_in_line(line):
    """Return [(position, amount_str)] for numeric amounts in the line."""
    matches = []
    # Decimal-dot amounts (allow optional space after dot and comma thousands).
    for m in re.finditer(r"\d{1,3}(?:,\d{3})+\.\s?\d{1,2}|\d+\.\s?\d{1,2}", line):
        amt = _parse_amount(m.group(0))
        if amt is not None:
            matches.append((m.start(), amt))
    if not matches:
        # Fallback for "538 00" style (space between integer and 2-digit cents).
        for m in re.finditer(r"\b(\d{1,3}(?:,\d{3})*)\s(\d{2})\b", line):
            amt = _parse_amount(m.group(1).replace(",", "") + "." + m.group(2))
            if amt is not None:
                matches.append((m.start(), amt))
    return matches


# -------- Total extraction --------


def _line_excluded(ul):
    if any(kw in ul for kw in EXCL_UNCONDITIONAL):
        return True
    if any(kw in ul for kw in EXCL_CONDITIONAL):
        # GST/SST only count as exclusion when not qualified by "incl*".
        if not any(q in ul for q in INCL_QUALIFIERS):
            return True
    return False


def _is_table_header(ul):
    return sum(1 for t in HEADER_TOKENS if t in ul) >= 1


def extract_total(text):
    lines = text.splitlines()
    upper_lines = [l.upper() for l in lines]

    stop_idx = len(lines)
    for i, ul in enumerate(upper_lines):
        if any(m in ul for m in STOP_MARKERS):
            stop_idx = i
            break

    has_rounding = any(
        any(m in upper_lines[i] for m in ROUNDING_MARKERS)
        for i in range(stop_idx)
    )

    for tier in TIER_KEYWORDS:
        candidates = []  # list of (line_index, amount_str)
        for i in range(stop_idx):
            ul = upper_lines[i]
            if _line_excluded(ul):
                continue
            matched_kw = None
            for kw in tier:
                if kw in ul:
                    matched_kw = kw
                    break
            if matched_kw is None:
                continue
            # Column-header false positives (e.g. "Qty  RSP  Amount").
            if matched_kw == "AMOUNT" and _is_table_header(ul):
                continue
            amts = _amounts_in_line(lines[i])
            if amts:
                candidates.append((i, amts[-1][1]))
                continue
            # Two-line fallback: keyword on one line, amount on the next.
            for j in range(i + 1, min(i + 3, stop_idx)):
                if not lines[j].strip():
                    continue
                if _line_excluded(upper_lines[j]):
                    break
                amts_next = _amounts_in_line(lines[j])
                if amts_next:
                    candidates.append((i, amts_next[-1][1]))
                break
        if candidates:
            # When any rounding/adj marker exists, the final rounded total is
            # the last surviving candidate; otherwise fall back to the first.
            return candidates[-1][1] if has_rounding else candidates[0][1]
    return None


# -------- Per-image aggregation --------


def process_image(img_path):
    outputs = ocr_variants(img_path)
    dates = []
    totals = []
    for text in outputs:
        d = extract_date(text)
        t = extract_total(text)
        if d is not None:
            dates.append(d)
        if t is not None:
            totals.append(t)

    def _pick(values):
        if not values:
            return None
        return Counter(values).most_common(1)[0][0]

    return _pick(dates), _pick(totals)


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    filenames = sorted(
        f for f in os.listdir(SRC_DIR)
        if f.lower().endswith((".jpg", ".jpeg", ".png"))
    )

    for name in filenames:
        d, t = process_image(os.path.join(SRC_DIR, name))
        print(f"{name}: date={d}, total={t}")
        ws.append([name, d, t])

    wb.save(OUT_FILE)
    print(f"Saved {OUT_FILE}")


if __name__ == "__main__":
    main()
