                amts_next = _amounts_in_line(lines[j])
                if amts_next:
                    candidates.append((i, amts_next[-1][1]))
                break
        if candidates:
            # When any rounding/adj marker exists, the final rounded total is
            # the last surviving candidate; otherwise fall back to the first.
            return candidates[-1][1] if has_rounding else candidates[0][1]
    return None


# -------- Per-image aggregation --------


def process_image(img_path):
    outputs = ocr_variants(img_path)
    dates = []
    totals = []
    for text in outputs:
        d = extract_date(text)
        t = extract_total(text)
        if d is not None:
            dates.append(d)
        if t is not None:
            totals.append(t)

    def _pick(values):
        if not values:
            return None
        return Counter(values).most_common(1)[0][0]

    return _pick(dates), _pick(totals)


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    filenames = sorted(
        f for f in os.listdir(SRC_DIR)
        if f.lower().endswith((".jpg", ".jpeg", ".png"))
    )

    for name in filenames:
        d, t = process_image(os.path.join(SRC_DIR, name))
        print(f"{name}: date={d}, total={t}")
        ws.append([name, d, t])

    wb.save(OUT_FILE)
    print(f"Saved {OUT_FILE}")


if __name__ == "__main__":
    main()
