    lines = text.splitlines()
    upper_lines = [l.upper() for l in lines]

    def _line_excluded(ul):
        return any(kw in ul for kw in EXCLUSIONS)

    def _tier_match(ul, keywords):
        return any(kw in ul for kw in keywords)

